import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/claims';
import { liveHolds, usePeople } from '../people/people';
import { useRates } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';
import { useFloor, useLate } from '../access/access';
import { personOverdue } from '../overdue/overdue';
import { useUser } from '../session/session';
import { useMyRole } from './dashboard';

// The steward's dashboard: over the sheet, how many claims are PENDING, how many are in REVIEW, and
// how many overdue claims count (the same figure as the sheet's overdue count). Shown only to a user
// acting as a steward — the cells are empty for anyone else; as of a date, by the role they had then.
function Dashboard({ sheetId }: { sheetId: string }) {
  const [user] = useUser();
  const role = useMyRole(sheetId, user).data;
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);

  const steward = role === 'steward';
  const overdue = people
    .map((p) => personOverdue(rates, p.grades, today, claims.filter((c) => c.personId === p.id), liveHolds(p, today), floor, late))
    .reduce((n, o) => n + o.count, 0);
  const shown = (n: number) => (steward ? String(n) : '');

  return (
    <section data-testid="dashboard">
      Steward: PENDING <strong data-testid="dash-pending-count">{shown(claims.filter((c) => c.status === 'PENDING').length)}</strong>,
      REVIEW <strong data-testid="dash-review-count">{shown(claims.filter((c) => c.status === 'REVIEW').length)}</strong>,
      overdue <strong data-testid="dash-overdue-count">{shown(overdue)}</strong>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: -98, Component: Dashboard });
        List<Boolean> archived = jdbc.query("SELECT archived AND (archived_on IS NULL OR archived_on <= ?) AS archived_then"
                + " FROM sheet WHERE id = ?", (rs, n) -> rs.getBoolean("archived_then"), Date.valueOf(day), sheet.id());
        return new Sheet(sheet.id(), day, !archived.isEmpty() && archived.get(0));
    }

    /** The sheet's parent sheet's id, or null when it has none (or was never loaded). */
    public String parent(String id) {
        List<String> found = jdbc.query("SELECT parent_id FROM sheet WHERE id = ?",
                (rs, n) -> rs.getString("parent_id"), id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The ids of the sheets naming this one as their parent, in id order. */
    public List<String> children(String id) {
        return jdbc.query("SELECT id FROM sheet WHERE parent_id = ? ORDER BY id", (rs, n) -> rs.getString("id"), id);
    }

    /**
     * The sheets of the sheet's tree, not the sheet itself: its ancestors (its parent, theirs and so
     * on) and its descendants (the sheets naming it as their parent, those naming them and so on),
     * among the sheets that exist, each once.
     */
    public java.util.Set<String> tree(String id) {
        java.util.Set<String> seen = new java.util.LinkedHashSet<>(List.of(id));
        for (String at = parent(id); at != null && seen.add(at); at = parent(at)) {
            // walked up to the root, stopping at a sheet already seen
        }
        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(id));
        while (!pending.isEmpty()) {
            for (String child : children(pending.removeFirst())) {
                if (seen.add(child)) pending.addLast(child);
            }
        }
        seen.remove(id);
        return seen;
    }

    /**
     * The sheet's descendants (the sheets naming it as their parent, those naming them and so on),
     * each once and never the sheet itself, in id order.
     */
    public List<String> descendants(String id) {
        java.util.Set<String> seen = new java.util.TreeSet<>();
        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(id));
        while (!pending.isEmpty()) {
            for (String child : children(pending.removeFirst())) {
                if (!child.equals(id) && seen.add(child)) pending.addLast(child);
            }
        }
        return new java.util.ArrayList<>(seen);
    }

    /** Names the sheet's parent sheet (null: none). */
    public void saveParent(String id, String parent) {
        jdbc.update("UPDATE sheet SET parent_id = ? WHERE id = ?", parent, id);
    }
package net.officefloor.hq.app.sheet;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/**
 * The sheet's descendants: the sheets naming it as their parent, the sheets naming those, and so
 * on. Each is listed once, and never the sheet itself.
 */
public class RespondWithDescendants {
    public void respond(@Val Sheet sheet, SheetRepository repository, ObjectResponse<DescendantsResponse> response) {
        List<String> descendants = new ArrayList<>();
        Set<String> seen = new HashSet<>(Set.of(sheet.id()));
        Deque<String> pending = new ArrayDeque<>(List.of(sheet.id()));
        while (!pending.isEmpty()) {
            for (String child : repository.children(pending.removeFirst())) {
                if (seen.add(child)) {
                    descendants.add(child);
                    pending.addLast(child);
                }
            }
        }
        response.send(new DescendantsResponse(descendants));
    }
}
