        }
        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(id));
        while (!pending.isEmpty()) {
            for (String child : children(pending.removeFirst())) {
                if (seen.add(child)) pending.addLast(child);
            }
        }
        seen.remove(id);
        return seen;
